command:
// Foundry VTT Macro: Валидация данных компендиумов (смоук-тест целостности)
// Сканирует все Item-компендиумы dedrel.* и ищет проблемы, которые ломают
// механику или синхронизацию с Obsidian (scripts/export_foundry_to_markdown.py):
//   ERROR — пустые system.key, дубликаты ключей, ключи не в snake_case,
//           запятые внутри ссылочных массивов (рантайм сплитит только по ";"),
//           нерезолвящиеся ссылки (adds_items, chain_trigger_maneuvers,
//           prerequisites_talents/mutations).
//   WARN  — элементы массивов, склеенные через ";" (работает, но лучше разнести),
//           дубликаты и пустые строки в массивах, нарушение префиксов
//           (manеuver_* у манёвров, отсутствие condition_ у кондиций),
//           несогласованность стаков у кондиций, фаза Active Effect для
//           system.*-изменений не "apply" (см. FOUNDRY V14 QUIRKS, раздел 12).
// Запускать ГМом после массовых правок контента и перед экспортом в маркдаун.
(async () => {
  // Типы, для которых system.key обязателен (кросс-ссылки и имена файлов)
  const KEY_REQUIRED = ["talent", "mutation", "maneuver", "condition", "spell"];
  const LINK_FIELDS = ["adds_items", "chain_trigger_maneuvers", "prerequisites_talents", "prerequisites_mutations"];
  // Пререк-массивы БЕЗ ссылок на предметы (атрибуты/навыки/линии крови): по ним
  // проверяем только мусорные пустые элементы. Пустой элемент "" ломает проверку
  // пререков (checkPrerequisites считает его невыполненным требованием), поэтому
  // ловим его отдельно — не как косметику, а как проблему логики.
  const PREREQ_SCALAR_FIELDS = ["prerequisites_attributes", "prerequisites_skills", "prerequisites_bloodlines"];
  const KEY_RE = /^[a-z0-9_]+$/;

  const packs = game.packs.filter(p => p.documentName === "Item" && p.collection.startsWith("dedrel."));
  if (!packs.length) return ui.notifications.error("Item-компендиумы dedrel.* не найдены.");

  ui.notifications.info(`Валидация данных: сканирую ${packs.length} компендиумов...`);

  // --- Проход 1: загрузка документов, глобальный индекс ключей и имён ---
  const all = []; // { pack, item }
  const byKey = new Map(); // key -> [{ label, type }]
  const names = new Set(); // имена (lowercase) для резолва ссылок
  for (const pack of packs) {
    const docs = await pack.getDocuments();
    for (const item of docs) {
      all.push({ pack: pack.collection, item });
      names.add(item.name.trim().toLowerCase());
      const key = (item.system?.key ?? "").trim();
      if (key) {
        if (!byKey.has(key)) byKey.set(key, []);
        byKey.get(key).push({ label: `${pack.collection} / ${item.name}`, type: item.type });
      }
    }
  }

  const issues = []; // { severity: "ERROR"|"WARN", where, text }
  const add = (severity, pack, item, text) =>
    issues.push({ severity, where: `${pack.replace("dedrel.", "")} / ${item.name}`, text });
  let emptyStrings = 0; // мусорные "" в ссылочных массивах — сводкой, иначе затопят отчёт
  let emptyPrereqs = 0; // мусорные "" в скалярных пререк-массивах (артефакт импорта [""])

  // Дубликаты ключей — глобально. Внутри одного типа — ошибка (забытая копия);
  // между типами — предупреждение (может быть намеренная связка талант <-> кондиция).
  for (const [key, owners] of byKey) {
    if (owners.length > 1) {
      const sameType = new Set(owners.map(o => o.type)).size === 1;
      issues.push({
        severity: sameType ? "ERROR" : "WARN",
        where: owners.map(o => o.label).join("<br>"),
        text: `Дубликат ключа «${key}» (${owners.length} шт.)${sameType ? "" : " — разные типы, проверьте что это намеренно"}`
      });
    }
  }

  // --- Проход 2: подокументные проверки ---
  for (const { pack, item } of all) {
    const sys = item.system ?? {};
    const key = (sys.key ?? "").trim();

    // Ключи
    if (KEY_REQUIRED.includes(item.type) && typeof sys.key === "string" && !key) {
      add("ERROR", pack, item, "Пустой system.key");
    }
    if (key && !KEY_RE.test(key)) {
      add("ERROR", pack, item, `Ключ не в snake_case: «${key}»`);
    }
    if (item.type === "maneuver" && key && !key.startsWith("maneuver_")) {
      add("WARN", pack, item, `Ключ манёвра без префикса maneuver_: «${key}»`);
    }
    if (item.type === "condition" && key.startsWith("condition_")) {
      add("WARN", pack, item, `Ключ кондиции с лишним префиксом condition_: «${key}» (файл станет condition_condition_...)`);
    }

    // Ссылочные массивы
    for (const field of LINK_FIELDS) {
      const values = sys[field];
      if (!Array.isArray(values)) continue;
      const seen = new Set();
      for (const raw of values) {
        if (typeof raw !== "string") continue;
        if (!raw.trim()) {
          emptyStrings++;
          continue;
        }
        if (raw.includes(",")) {
          add("ERROR", pack, item, `${field}: запятая внутри элемента — рантайм это НЕ расщепит: «${raw}»`);
        }
        if (raw.includes(";")) {
          add("WARN", pack, item, `${field}: элементы склеены через «;» — лучше разнести по элементам массива: «${raw}»`);
        }
        for (const part of raw.split(/[;,]/).map(s => s.trim()).filter(Boolean)) {
          if (seen.has(part)) add("WARN", pack, item, `${field}: дубликат «${part}»`);
          seen.add(part);
          // "any" — легитимный wildcard триггеров цепи: срабатывает после
          // любого манёвра (см. chain-maneuvers-hud.mjs, isAny)
          if (field === "chain_trigger_maneuvers" && part.toLowerCase() === "any") continue;
          if (!byKey.has(part) && !names.has(part.toLowerCase())) {
            add("ERROR", pack, item, `${field}: ссылка «${part}» не найдена ни по ключу, ни по имени`);
          }
        }
      }
    }

    // Пустые элементы в скалярных пререк-массивах (атрибуты/навыки/линии крови).
    // Именно они (а не только talents/mutations) ломали проверку пререков.
    for (const field of PREREQ_SCALAR_FIELDS) {
      const values = sys[field];
      if (!Array.isArray(values)) continue;
      for (const raw of values) {
        if (typeof raw !== "string" || !raw.trim()) emptyPrereqs++;
      }
    }

    // Кондиции: согласованность стаков
    if (item.type === "condition") {
      if (sys.stackable && (sys.max_stacks ?? 1) <= 1) {
        add("WARN", pack, item, "stackable: true, но max_stacks <= 1");
      }
      if (!sys.stackable && (sys.max_stacks ?? 1) > 1) {
        add("WARN", pack, item, `stackable: false, но max_stacks = ${sys.max_stacks}`);
      }
      if (!sys.stackable && (sys.tick?.formula ?? "").includes("@stacks")) {
        add("WARN", pack, item, "tick.formula использует @stacks, но stackable: false");
      }
    }

    // Active Effects: фазы system.*-изменений
    for (const eff of item.effects ?? []) {
      const changes = [...(eff.system?.changes ?? []), ...(eff.changes ?? [])];
      for (const ch of changes) {
        if (!ch?.key) {
          add("WARN", pack, item, `Эффект «${eff.name}»: изменение без key`);
          continue;
        }
        if (ch.key.startsWith("system.") && ch.phase !== "apply") {
          add("WARN", pack, item, `Эффект «${eff.name}»: ${ch.key} имеет фазу «${ch.phase ?? "нет"}» вместо «apply» — может затираться в prepareDerivedData (QUIRKS §12)`);
        }
      }
    }
  }

  if (emptyStrings) {
    issues.push({ severity: "WARN", where: "везде", text: `Пустые строки "" в ссылочных массивах: ${emptyStrings} шт. — косметика, вычищается при пересохранении листа` });
  }
  if (emptyPrereqs) {
    issues.push({ severity: "WARN", where: "везде", text: `Пустые элементы "" в пререк-массивах (атрибуты/навыки/линии крови): ${emptyPrereqs} шт. — прогоните normalize_prerequisites_macro.js (checkPrerequisites их игнорирует, но данные грязные)` });
  }

  // --- Отчёт: полностью в консоль (F12), в чат ничего не пишем ---
  const errors = issues.filter(i => i.severity === "ERROR");
  const warns = issues.filter(i => i.severity === "WARN");
  const toRow = i => ({ "Где": i.where.replaceAll("<br>", " | "), "Проблема": i.text });

  console.group(`%cDedrel | Валидация данных: ${all.length} документов — ошибок: ${errors.length}, предупреждений: ${warns.length}`,
    "font-weight:bold;font-size:13px;");
  if (errors.length) {
    console.group(`%cERROR (${errors.length})`, "color:red;font-weight:bold;");
    console.table(errors.map(toRow));
    console.groupEnd();
  }
  if (warns.length) {
    console.group(`%cWARN (${warns.length})`, "color:darkorange;font-weight:bold;");
    console.table(warns.map(toRow));
    console.groupEnd();
  }
  if (!issues.length) console.log("%cПроблем не найдено.", "color:green;font-weight:bold;");
  console.groupEnd();

  ui.notifications[errors.length ? "error" : warns.length ? "warn" : "info"](
    `Валидация данных: ${errors.length} ошибок, ${warns.length} предупреждений — отчёт в консоли (F12).`);
})();
